import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"The Trinity of Consistency as a Defining Principle for General World Models","description":"","frontmatter":{"title":"The Trinity of Consistency as a Defining Principle for General World Models","arxiv":"2602.23152","date":"2026-02-26","authors":"Jingxuan Wei, Siyuan Li, Yuhang Xu, Zheng Sun, Junjie Jiang, Hexuan Jin, Caijun Jia, Honghao He, Xinglong Xu, et al.（共 24 位，含 Ran He、Zhen Lei、Stan Z. Li、Shuicheng Yan、Cheng Tan）","categories":"cs.AI","topics":"世界模型定义, 一致性理论, 统一多模态模型","outline":[2,2]},"headers":[],"relativePath":"papers/2602.23152.md","filePath":"papers/2602.23152.md","lastUpdated":null}'),e={name:"papers/2602.23152.md"};function l(r,s,o,i,c,m){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="the-trinity-of-consistency-as-a-defining-principle-for-general-world-models" tabindex="-1">The Trinity of Consistency as a Defining Principle for General World Models <a class="header-anchor" href="#the-trinity-of-consistency-as-a-defining-principle-for-general-world-models" aria-label="Permalink to &quot;The Trinity of Consistency as a Defining Principle for General World Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2602.23152" target="_blank" rel="noreferrer">2602.23152</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-02-26</td></tr><tr><td><strong>作者</strong></td><td>Jingxuan Wei, Siyuan Li, Yuhang Xu, Zheng Sun, Junjie Jiang, Hexuan Jin, Caijun Jia, Honghao He, Xinglong Xu, et al.（共 24 位）</td></tr><tr><td><strong>分类</strong></td><td>cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>主张通用世界模型必须同时满足模态/空间/时间三种一致性，并用 1,485 题、18 子任务的 CoW-Bench 把视频生成模型与统一多模态模型放进同一套四帧网格、0–2 打分的约束满足协议，暴露出普遍的 constraint backoff（惄意放松约束）。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">文献定位</p><p>119 页、50 图，只有 v1。结构是&quot;概念框架 + 系统性综述 + benchmark&quot;三合一：§2 逐个拆解三种一致性的理论基础，§3 讲两两融合，§4 讨论挑战与现有 benchmark 的四重缺陷，§5 才是 CoW-Bench 本体，§6 结论。Leading authors 为 Jingxuan Wei、Siyuan Li、Cheng Tan；通讯作者为 Conghui He、Shuicheng Yan、Cheng Tan。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>「世界模型」这个词在过去两年被用得极其宽松。Sora 之后，一个能把文本变成连贯视频的扩散模型被叫做世界模型；一个在 Atari 里做 latent imagination 的 RSSM 也被叫做世界模型；一个能预测下一帧占据栅格的自动驾驶模块同样被叫做世界模型。这些系统的输入输出、训练目标、失败模式完全不同，却共用一个名字。后果是实证层面的：当我们说某个模型「更接近世界模型」时，没有可核验的判据能支撑这句话，只能拿 FVD、VBench 分数或者几个 cherry-pick 的视频当证据。</p><p>论文明确声称的问题正是这个定义空缺——摘要原话是「the field still lacks a principled theoretical framework that defines the essential properties requisite for a General World Model」。它给出的答案是一组三元判据：Modal Consistency 作为语义接口，Spatial Consistency 作为几何基底，Temporal Consistency 作为因果引擎。</p><p>这件事的价值不在于多一个定义，而在于把一个模糊的工程口号转成可以证伪的属性清单。如果三条判据成立，那么「这个模型是不是世界模型」就不再是修辞问题，而是三组可测量的性质；缺哪一条，就能预言它会在什么任务上塌掉。论文同时给出 CoW-Bench 来承接这套判据，说明作者不打算停在概念层。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>定义侧</strong>。Ha 与 Schmidhuber 2018 把世界模型定义成&quot;压缩表示 + 转移预测&quot;，这是 RL 语境下的操作性定义；LeCun 的 JEPA 路线把它定义成&quot;在抽象表示空间做预测&quot;；Sora 技术博客则用&quot;video generation models as world simulators&quot;把定义直接绑到生成质量上。论文在结论里把这三条重排成一条<strong>按动作空间表达力分级的谱系</strong>：Vector-as-Action（JEPA，潜空间预测但交互机制不可解释）→ Key-as-Action（Genie 系列，受限于预定的离散控制空间）→ Prompt-as-Action（用语义编译器把自然语言意图翻译成通用时空仿真）。这条谱系比单纯罗列定义有信息量，也是全文结论部分真正的论断：一致性违反不是数据不够，而是<strong>交互表示方式的结构性产物</strong>。</p><p><strong>评测侧的四重缺陷</strong>。§4.2.4 是全文最尖锐的一节，它把现有 benchmark 的问题列成四条，而且每条都点名：</p><ol><li><strong>指标软天花板与判官幻觉</strong>。TiViBench、V-ReasonBench 这类基准过度依赖 GPT-4o / Gemini 当裁判，而 VLM 对摩擦系数、流体黏度这类细粒度物理属性的感知精度极低，常常只要帧间流畅就给高分，即使它违反牛顿第三定律。作者明说，自反思/critic 模型与更细的 rubric 都只是打补丁，真正缺的是<strong>基于仿真引擎 ground truth 的硬验证</strong>。</li><li><strong>分布内记忆掩盖 OOD 缺陷</strong>。现有数据集多采自真实视频或标准游戏录像，高分往往来自过拟合而非可迁移的世界规律。</li><li><strong>长序列误差累积与缺乏过程验证</strong>。绝大多数基准只测 10 秒以内，而生成架构本身没有在线过程验证器与物理约束修正模块，微小误差会随时间指数放大。</li><li><strong>缺乏主动干预的因果探针</strong>。现有评测都是旁观者模式，只问&quot;接下来会发生什么&quot;，不问&quot;如果此刻抽掉支撑，轨迹会怎么变&quot;。</li></ol><p>这四条列得很好，但也给自己埋下了雷：CoW-Bench 自己只正面解决了第二条（自建题库、单一一致性变量受控），第一、三、四条在它自己的协议里基本原封不动。§9 会回到这一点。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>不用本文的结论作前提，可以这样一步步走到三元判据。</p><p>第一步是观察失败模式的分布。视频生成模型的典型崩塌有三类：说好的物体没出现或者中途换成别的东西（语义层）；镜头一转，房间的布局对不上，物体互相穿模（几何层）；动作顺序错乱、因果倒置，杯子先碎后落（时间层）。这三类失败几乎不重叠，修好一类不会自动修好另一类。</p><p>第二步是问：为什么它们不重叠？因为它们各自绑定不同的表示。语义失败源于文本与像素之间的对齐界面；几何失败源于模型内部有没有稳定的 3D 结构；时序失败源于模型是在拟合帧间统计还是在建模状态转移。三条独立的失败轴，自然对应三条独立的必要条件。</p><p>第三步是看架构演进给了什么线索。早期系统是松耦合的：一个 text encoder、一个 diffusion backbone、一个可选的深度/光流模块，各管一摊。近两年的 UMM 把感知、语言、推理压进同一个骨干。§2.1 把这条线索写成了一个具体的依赖链：模态对齐得到的统一表征空间为几何重建提供语义先验，而空间一致性的 3D 流形反过来为时间演化提供物理约束——三者不是并列的质量维度，而是有依赖顺序的层次。</p><p>第四步是承认光有框架不够，必须能测，而且现有的测法不能用。§4.2.4 把理由列得很硬（见 §2），其中一条直接决定了 CoW-Bench 的题库要自建：从真实视频采集的数据会让高分来自死记硬背而非可迁移的世界规律。既然三条判据分别对应语义、几何、因果，评测就应该把三面拆开分别逐一逗出来，再用两两交叉逗出真正的断裂——于是有了六家族与单一变量控制协议。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>世界模型不是「能生成逼真视频的模型」，而是「在语义、几何、因果三个坐标上同时自洽的模型」。这三条不是并列的质量维度，而是有层次的：模态一致性提供进出这个模型的接口，空间一致性提供状态存放的基底，时间一致性提供状态如何演化的规则。缺接口，模型无法被指令；缺基底，状态无处可存；缺规则，演化退化成外插。先前方法之所以看着像世界模型又用着不像，是因为它们通常只在一条坐标上做到位，另外两条靠数据规模掩盖过去。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>框架侧已在 §2–§3 描述，这里只走 CoW-Bench 的完整流程。</p><p><strong>任务蓝图</strong>。三个单一一致性 + 三个两两交叉，共六个家族，每家族再拆三个子任务（基础/结构化/复杂约束三个难度档），共 18 个：</p><ul><li><strong>M</strong>：风格/材质迁移 · 细粒度控制 · 多约束组合</li><li><strong>S</strong>：平面布局 · 层次遮挡 · 多视图 3D 结构</li><li><strong>T</strong>：世界线持续性 · 规则引导演化 · 有序阶段转换</li><li><strong>M×S</strong>：语义平面绑定 · 语义层次控制 · 语义 3D 视图一致</li><li><strong>M×T</strong>：长时程锚定 · 属性动态对齐 · 触发事件合规</li><li><strong>S×T</strong>：平面迷宫轨迹 · 遮挡动力学 · 3D 回环导航连贯性</li></ul><p><strong>单一一致性变量控制协议</strong>。这是题目设计阶段最值得学的一条：每个子任务只允许与目标一致性直接相关的变量变化，实体数量、背景复杂度、镜头运动、运动幅度、遮挡条件这些混淆因素被显式钉死，以便把模型行为稳定归因到目标能力。</p><p><strong>种子构造与审核</strong>。先用推理能力强的模型造种子样本，目标不是&quot;生成符合描述的样本&quot;而是&quot;设计能真正触发对应失败模式的难例&quot;。每个种子采统一结构：<code>inputText</code>、<code>inputImageDesc</code>、<code>outputImageExpect</code>、<code>outputVideoExpect</code>，把条件/初始态/目标结果绑成可验证单元；之后经过人机协同的多源审核。</p><p><strong>规模与平衡</strong>。1,485 个样本，每个子任务 69–91 例（另含 50 例难度更高的 Maze），作者强调这种均匀分布是为了避免长尾带来的评测偏差。难度梯度用三个量描述：指令长度从 Modal-Subj-Attr 的平均 7.1 词到 Modal-Multi-Require 的 74.8 词；视觉复杂度用平均元素数（跨模态任务如 3D-Reconstruct 平均 2.1，高于单模态的 1.6）；动态复杂度用动作描述长度（Time-State 高达平均 77.7 词）。</p><p><strong>指标：原子分解</strong>。评测被形式化为<strong>约束满足问题</strong>：给定文本条件、参考图或初始态，输出必须满足其中隐含或明说的约束。作者把反复出现的失败模式抽成 16 个可复用的<strong>原子检查</strong>（A1–A16），再用它们组合出 18 个<strong>指标家族</strong>（M1–ST3），每家族配五个可读的子指标（如 Id+Attr、Min-change、Inter-state、Persp/Scale、Occ-update、Geo-self、Env-stab）。这套设计的目的是可归因（每个原子对应一个具体失败机制）与跨任务可比（同一原子在不同家族里语义一致）。</p><p><strong>评分协议：2×2 网格</strong>。这是全文最关键也最应该被看清楚的一条。对视频任务，<strong>按时间顺序均匀采样 4 帧</strong>；对图像任务，则让模型<strong>按时间顺序生成四张关键图</strong>。四帧拼成 2×2 网格（左上→右下），评分者逐帧分析、不得跳帧，按与指标家族对齐的五问链逐项给 0–2 分并附理由：0 = 明确违反，1 = 部分满足但有歧义或证据不足，2 = 清晰稳定无争议地满足。样本级分数先在子指标内平均，再在同家族的子任务间等权聚合；总分 AVG 从原始 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">10</span><span class="mclose">]</span></span></span></span> 重标到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">100</span><span class="mclose">]</span></span></span></span>。</p><p>论文给出了完整的评分 prompt 模板（Role / Input / Task / Scoring / Rules / Output，要求输出 <code>QuestionX, Score, Rationale</code>），但<strong>并未在正文里点名执行打分的模型</strong>；从模板形式看应为 LMM 判官，而 §4.2.4 与结论只说检查清单是&quot;人类专家推理&quot;设计的。这个缺口很重要，§9 会展开。</p><p><strong>被测模型</strong>。四类：闭源视频（Sora、Kling）、闭源图像（GPT-image-1、GPT-image-1.5、Nano Banana、Nano Banana Pro、Seedream-4-0、Seedream-4-5）、开源视频（Allegro、HunyuanVideo、LTX-Video、CogVideoX、EasyAnimate、Wan2.2-I2V-14B、SkyReels-V2）、开源图像/统一模型（Qwen-Image、BAGEL、UniVideo、Emu3.5）。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>论文本身是综述式的，但 §2 确实给了三条一致性各自的形式化基底，而且选的都是领域内现成的方程，不是自造的符号。</p><p><strong>模态一致性 = 联合逆投影</strong>。作者从 Platonic Representation Hypothesis 出发：存在一个客观的潜在物理状态空间 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0794em;">Z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0794em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">world</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，图像与文本是它向不同低维子空间的投影。模态一致性就是从观测到的&quot;影子&quot; <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">img</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">txt</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span> 反推共享潜变量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span></span></span></span>。这是个典型的病态问题：视觉投影 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">img</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 保留大量高频物理熵，文本投影 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">txt</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 则高度抽象成离散符号，<strong>熵不对称</strong>是对齐的首要障碍。CLIP 一系用超球面假设把特征挤到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord mathbb">S</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">d</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span></span></span></span></span></span></span></span> 上，但 Liang 等的 cone effect 表明联合优化会把视觉与文本嵌入压成两个狭窄且分离的锥形区；从流形角度看，视觉数据在连续稠密的低维流形上，语言数据是稀疏离散聚类，<strong>流形非同胚</strong>，因此完美等距对齐本身就是病态的。</p><p><strong>空间一致性 = 时空流形上的耦合逆微分问题</strong>。在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8193em;vertical-align:-0.136em;"></span><span class="mord mathcal">M</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">⊆</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8974em;vertical-align:-0.0833em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">3</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7713em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7713em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">+</span></span></span></span></span></span></span></span></span></span></span></span> 上构造状态场 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">Φ</span><span class="mopen">(</span><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span></span></span></span>，服从三条定律。其一是渲染，即辐射传输方程（RTE）：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol">d</span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∇</span><span class="mord mathnormal">L</span><span class="mopen">(</span><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol">d</span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mopen">(</span><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="mclose">)</span><span class="mord mathnormal">L</span><span class="mopen">(</span><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol">d</span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mopen">(</span><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="mclose">)</span><span class="mord"><span class="mord"><span class="mord boldsymbol">c</span></span></span><span class="mopen">(</span><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol">d</span></span></span><span class="mclose">)</span><span class="mpunct">,</span></span></span></span></span></p><p>作者的观点很好：NeRF 与 3DGS 只是它的两种离散化——前者沿射线做黎曼和积分（保连续性），后者把连续场拆成拉格朗日高斯基函数后解析光栅化（保实时性）。其二是生成演化，建模为从高斯噪声恢复到数据流形的随机微分方程</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord mathnormal">d</span><span class="mord"><span class="mord">Φ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.1104em;">f</span></span></span><span class="mopen">(</span><span class="mord"><span class="mord">Φ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">d</span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">d</span><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.0278em;">w</span></span></span><span class="mpunct">,</span></span></span></span></span></p><p>当 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 时退化为 ODE，即 flow matching。其三是运动定律，要求物质点沿时间轴服从拉格朗日输运以保拓扑一致。</p><p>这三条把&quot;空间一致性&quot;从一个形容词变成了可写出方程的性质，这是本文比一般综述扶实的地方。需要注意的是，<strong>这些方程与 CoW-Bench 的打分之间没有形式化的桥</strong>：评分最终落到的是四帧图上的五个 0–2 判断，而不是对 RTE 残差或拉格朗日输运偏差的测量。理论部分提供的是词汇与直觉，不是指标的推导基础。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>总榜（AVG，0–100）</strong>。GPT-image-1.5 85.62 第一，Nano Banana Pro 82.57，GPT-image-1 80.35，Nano Banana 78.38，开源的 Emu3.5 77.76，Kling 73.96，Seedream-4-5 73.82，Sora 73.66，Seedream-4-0 71.33，SkyReels-V2 65.37，Wan2.2-I2V-14B 61.83，UniVideo 59.96，BAGEL 59.34，Allegro 52.67，Qwen-Image 17.77。<strong>排在最前面的全部是图像生成/统一模型，两个旗舰视频模型只到中游</strong>。这个结果对一个&quot;世界模型&quot;基准来说非常反直觉，§11 会把它当作主攻点。</p><p><strong>发现一：瓶颈在时间控制而不在连贯性</strong>。T-WL（世界线持续性）即使对视频模型也普遍很高（Sora 达 9.32），说明把画面拍得连贯已不是难处；但需要规则引导演化或结构化状态推进的任务（T-Rule、T-Stage-Order）模型间差异极大。作者的总结很准：世界模型需要的是时间上的约束满足，而不是平滑。</p><p><strong>发现二：单视图 3D 很强，全局锚定很弱</strong>。S-3D 上多数头部模型超过 9.0（Nano Banana Pro 9.61），但 TS-Maze-2D 这类需要在运动中保持全局空间结构的任务全面崩盘：<strong>Nano Banana Pro 只有 4.46，Seedream-4-5 只有 2.28，Sora 4.17，Kling 5.30，Allegro 1.86</strong>，即使总榜第一的 GPT-image-1.5 也只有 7.26。局部几何合理性远比全局世界状态维护容易。</p><p><strong>发现三：跨维度任务才是分水岭</strong>。MT-PropKeep（属性在时间演化中保持）头部模型接近天花板，但 MT-PropChange（属性变化对齐）与 TS-Maze-2D 上退化严重。作者的结论是：即使逐帧保真度很好，全局世界状态维护与轨迹级约束执行仍未解决。</p><p><strong>发现四：constraint backoff</strong>。这是全文命名最好的一个现象：模型会把罕见或严格的约束<strong>静默地替换成更常见的默认值</strong>（罕见材质退回普通材质、局部编辑扩散成全局漂移、同一世界线逐帧重初始化、遮挡时前后景关系反转、多视图下重画另一个世界），而这些失败在视觉上都很“看得过去”。开源视频模型尤其如此：它们要么把罕见约束退化成默认，要么保住了运动却丢了身份与属性。</p><p>作者在结论里把这件事归因得很远：constraint backoff 不是数据量或规模不够，而是<strong>当前模型表示&quot;交互&quot;的方式的结构性产物</strong>——动作空间要么不可解释（Vector-as-Action）要么写死（Key-as-Action），模型根本没有把语义承诺接地到物理动力学上的表达能力。这一步从测量跳到机制，证据链是断的，属于作者的论断而非实验结论。</p><p>还有一处值得注意的内部不一致：§5.7 的 takeaway 写的是&quot;视频模型在指令跟随上优于图像模型，但根本性地缺乏物理演化逻辑&quot;，而表 9 的总榜是图像模型全面领先。两句话不必然矛盾（指令跟随不等于 AVG），但论文没有报告支撑前一句的子指标拆分。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：世界模型这个概念被滥用到失去判别力，论文用模态/空间/时间三种一致性重建它，并分别给出了联合逆投影、RTE/SDE/拉格朗日输运这些现成的形式化基底。CoW-Bench 把它操作化为 1,485 题、六家族、十八子任务，用 16 个原子检查组合出 18 个指标家族，每题只看四帧拼成的 2×2 网格并按五问链打 0–2 分。总榜上 GPT-image-1.5（85.62）、Nano Banana Pro（82.57）这类图像模型全面领先 Sora（73.66）与 Kling（73.96）。世界线持续性与单视图 3D 已接近天花板，而需要全局世界状态的 TS-Maze-2D 普遍崩盘（多数模型低于 5）。最有价值的发现是 constraint backoff：模型会把严格约束静默地换成常见默认值，而画面仍然好看。</p><p><strong>3 句话版</strong>：论文主张通用世界模型必须同时满足三种一致性，并把它们分别对应到语义错位、几何穿模、因果倒置三类失败。CoW-Bench 把两类架构放进同一约束满足协议，结果是图像模型反而赢了视频模型。真正的短板集中在时空跨维任务，尤其是需要保持全局空间结构的导航类题目。</p><p><strong>1 句话版</strong>：用&quot;三种一致性&quot;把&quot;什么算世界模型&quot;从修辞变成可测判据，并用四帧网格协议把隐性的&quot;约束退让&quot;量化出来。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>从整段输出里均匀取四帧拼成网格，足以判定一致性是否被违反</strong>。全部 1,485 题、全部 18 个指标家族、全部结论都建立在这个采样上。</p><p>它脆弱，因为<strong>论文自己在 §4.2.4 里把这类做法判了死刑</strong>。它批评现有 benchmark “只测 10 秒以内，掩盖了长程仿真的状态漂移”，并指出微小物理误差会随时间指数放大；它批评 GPT-4o / Gemini 当裁判会“只要帧间流畅就给高分”，并说真正的出路是基于仿真引擎 ground truth 的硬验证。然而 CoW-Bench 自己的协议是：<strong>把整段输出压成四帧</strong>（比它批评的对象采样得更稀），然后用一段 Role/Input/Task/Scoring/Rules/Output 的 prompt 模板去打 0–2 分，<strong>并未引入任何仿真引擎硬验证</strong>。</p><p>后果是可预测的：任何发生在采样帧<strong>之间</strong>的违反（穿模、瞬移、中途消失后又出现、动量不守恒）在构造上就不可见。而这恰恰是 T-WL（世界线持续性）普遍拿高分的最简单解释之一：四张相隔很远的帧里主体都在，并不能推出世界线全程持续。论文把 T-WL 高分解读成“拍得连贯已不是难处”，但同一数字与“协议看不到不连贯”完全兼容，两种解释没有被分离。</p><p>更关键的是，论文<strong>没有报告评分者与任何独立参照的一致性</strong>：没有点名执行打分的模型，没有人机一致性或人人一致性数字，也没有任何程序化可验证的子集作为锚点。于是“模型在惄惄退让约束”这个头条结论，是用它自己宣布不够格的那类仪器测出来的。</p><p>得公平地说，CoW-Bench 在两个方向上确实比它批评的对象强：题目是自建而非采自真实视频（缓解 OOD 记忆问题），并且有严格的单一变量控制与 69–91 例的均衡分布。脆弱的只是测量仪器，不是题库设计。</p><p>（上一版解读把“三条判据是否独立”当作最脆弱假设，拿到全文后应当修正：论文确实没有报告三组分数的相关矩阵，这仍是一个真实缺口，但它的代价远小于测量仪器本身不可信。）</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周之内可做，目标是直接检验 §9 的那条假设，而不是重复论文已做过的排名。</p><ul><li><strong>数据</strong>：造 60 个<strong>程序化可验证</strong>的场景，候选是 2D 迷宫导航（墙与目标已知）与刚体自由落体（轨迹可解析计算）。这两类恰好对应 CoW-Bench 的 TS 家族，且 ground truth 不需要人工判断。</li><li><strong>实现</strong>：对每个场景，用一个开源视频模型（Wan2.2-I2V 或 SkyReels-V2，两者都在论文名单里）生成一段完整视频；然后用两套尺子打分——(a) 论文的四帧 2×2 网格 + 五问链 0–2（用任一 LMM 执行）；(b) 程序化检查：逐帧追踪主体位置，直接判定是否穿墙、是否到达目标、落体加速度是否一致。</li><li><strong>测量</strong>：两套分数的 Spearman 相关；以及最关键的一个量——<strong>在四帧之间发生但四帧上看不见的违反占比</strong>。再把采样帧数从 4 扫到 8/16/32，看分数如何随帧数变化。</li><li><strong>判据</strong>：若四帧分与程序化分的相关低于 0.5，或者分数随采样帧数单调下降且降幅显著，那么 CoW-Bench 的绝对分与模型排序都需要重新评估。这个实验也直接回答了论文自己提出但未实现的“仿真引擎硬验证”诉求。</li></ul><p>这个实验的好处是它直接检验 §9 里最脆弱的那条假设，而不是重复论文已经做过的排名。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的反例不需要构造，<strong>它就在论文自己的表 9 里</strong>：一批<strong>根本不能生成视频</strong>的文生图模型（GPT-image-1.5 85.62、Nano Banana Pro 82.57）在一个世界模型基准上全面赢过了 Sora（73.66）与 Kling（73.96）。</p><p>原因藏在协议里：对视频模型，四帧是从<strong>一段连续 rollout</strong> 里均匀采出来的；对图像模型，四帧是它<strong>分四次、每次拿完整文本条件独立画出来</strong>的关键帧。后者根本不需要产出帧与帧之间的东西，也就不承担误差累积、连续动力学、实时状态维护这些成本——而这些恰恰是&quot;仿真器&quot;与&quot;纹理合成器&quot;的分界。换句话说，<strong>协议把最难的那部分从图像模型身上免除了，却仍然把两者放在同一张榜上排序</strong>。这个结果可以读成“图像模型更接近世界模型”，也可以读成“CoW-Bench 度量的是关键帧构图能力而非内部世界模拟”，而论文没有分离这两种解释。论文结论里“一个产出惊艳像素但维持不住跨维度一致性的系统仍然只是纹理合成器”这句话，恰好可以拿来反问它自己的榜首。</p><p>分离实验很容易做：把视频模型也改成&quot;分四次生成关键帧&quot;的赛道（或反过来，要求图像模型产出完整序列再采样），看排名是否翻转。若翻转，那么表 9 度量的主要是赛道差异而非世界模型能力。</p><p>第二条攻击：<strong>没有报告平凡基线</strong>。一个把初始帧复制四份的退化系统在 T-WL（世界线持续性）与各类“xx-stab”子指标上应当拿到满分，因为什么都没变就不会不一致。论文报了 15 个真实模型，却没有报任何地板，因此无法知道 Sora 的 T-WL 9.32 里有多少是&quot;保持世界线&quot;、多少是&quot;少动少错&quot;。考虑到作者自己观察到部分模型会&quot;保住运动却丢掉身份&quot;，反方向的退化（保住身份却不动）同样需要被控制。</p><p>第三条攻击：<strong>Qwen-Image 的 17.77 是个地板伪影</strong>。它比倒数第二的 Allegro（52.67）低了三十多分，很难相信这反映的是世界模型能力差距；更可能的解释是它无法按协议产出&quot;时间顺序的四张关键图&quot;。若如此，这一行度量的是接口兼容性而非一致性，应当从榜上标注而非直接参排。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：三条一致性都是「自洽性」判据——它们检查模型输出内部是否互相不矛盾，但都不检查模型是否知道自己在什么地方会错。论文自己命名的 <strong>constraint backoff</strong> 正是这个缺口的极端形态：模型把一个严格约束换成常见默认值时，输出依然自洽、依然流畅、依然一副胸有成竹的样子。论文把它归因于动作空间表达力，但还有一个更直接的缺口：没有任何判据要求模型在退让时<strong>降低自信度</strong>。</p><p><strong>新 framing</strong>：把第四条判据设为<strong>校准一致性（calibration consistency）</strong>，即模型对自身预测的不确定度必须随预测误差单调变化，并且这个不确定度要在语义、几何、时间三条通道上可分解——模型不仅要说「我不确定」，还要说清是「不知道这是什么」「不知道它在哪」还是「不知道接下来怎么变」。这不是给现有框架加一个模块，而是改变判据的类型：前三条是关于输出的，第四条是关于模型对输出的元判断。</p><p><strong>可借鉴的相邻领域工具</strong>：conformal prediction 提供了不依赖模型族假设的覆盖率保证，可以直接套到「未来 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 帧的状态集合预测」上，给出有限样本覆盖保证；主动学习里的 disagreement-based 不确定度分解，提供了把总不确定度拆成 aleatoric 与 epistemic 的现成手段，正好对应「世界本身随机」与「模型不知道」的区分。</p><p><strong>第一个实验</strong>：在一个可控物理场景集合上（例如刚体碰撞，参数如摩擦系数、质量比可枚举），把一部分参数区间留作 held-out。让模型对每个场景输出未来状态的预测集合，用 conformal 校准使 in-distribution 覆盖率达到 90%。然后在 held-out 参数上测实际覆盖率：如果掉到 50% 以下，说明当前的一致性判据完全没有约束住外推行为，第四条判据的必要性即被实证确立；如果仍能维持 80% 以上，说明前三条一致性在某种程度上蕴含了校准，那才是一个真正值得写进定义的强结论。</p>',75)])])}const d=a(e,[["render",l]]);export{h as __pageData,d as default};
